const responseId = "example-1";
return [{ json: {
  expectedId: responseId,
  statusCode: 200,
  requiredKeys: ["sku"],
  body: { jsonrpc: "2.0", id: responseId, result: {
    content: [{ type: "text", text: "{\"sku\":\"demo\"}" }],
    structuredContent: { sku: "demo" }
  } }
} }];

const items = $input.all();
return items.map(({ json }, index) => {
  const status = json.statusCode;
  const rpc = json.body;
  const reasons = [];
  if (!Number.isInteger(status) || status < 200 || status >= 300 || status === 207) reasons.push("transport");
  if (!rpc || rpc.jsonrpc !== "2.0" || rpc.id == null || rpc.id !== json.expectedId) reasons.push("response_id");
  if (rpc?.error !== undefined) reasons.push("jsonrpc_error");
  const result = rpc?.result;
  if (!result || result.isError === true) reasons.push("tool_error");
  const blocks = result?.content;
  const invalidBlock = !Array.isArray(blocks) || blocks.some((b) => !b || typeof b.type !== "string" || (b.type === "text" && (typeof b.text !== "string" || !b.text.trim())));
  if (invalidBlock) reasons.push("content");
  let data = result?.structuredContent;
  if (data === undefined && Array.isArray(blocks) && blocks.length === 1 && blocks[0]?.type === "text") {
    try { data = JSON.parse(blocks[0].text); } catch {}
  }
  const required = json.requiredKeys ?? [];
  if (!Array.isArray(required) || required.some((key) => typeof key !== "string" || !data || typeof data !== "object" || Array.isArray(data) || !Object.hasOwn(data, key) || data[key] == null)) reasons.push("required_keys");
  if (reasons.length) throw new Error("MCP Guard rejected item " + index + " (" + reasons.join(", ") + ")");
  return { json: { verified: true, requestId: rpc.id, result }, pairedItem: { item: index } };
});
